40	/// A question in the pane: saved with the project, by its place among the
41	/// saved questions, or asked since, by its id.
42	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
43	pub(super) enum QuestionKey {
44	    Answer(usize),
45	    Ask(usize),
46	}
47	
48	impl QuestionKey {
49	    /// Numbers its table apart from every other, in its rows' element ids and
50	    /// its markdown's keys.
51	    fn table(self) -> usize {
52	        match self {
53	            Self::Answer(ix) => ASK_HISTORY_IX + ix,
54	            Self::Ask(id) => ASK_IX - id,
55	        }
56	    }
57	
58	    /// Its element ids, apart from every other question's.
59	    fn id(self) -> usize {
60	        self.table()
61	    }
62	}
63	
64	/// What a row of the pane's list shows.
65	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
66	enum PaneRow {
67	    /// A question's box, headed by a divider when it begins a conversation.
68	    Question(usize),
69	    /// Its status line: while it runs, the latest thing the harness did.
70	    Status(usize),
71	    /// Its table's header, or "No output." for a finished one with none.
72	    TableHeader(usize),
73	    /// A row of its table.
74	    TableRow(usize, usize),
75	    /// The end of its table.
76	    End(usize),
77	    /// After the last question: the divider New conversation put in, if the
78	    /// next question starts one, and the margin ending the list.
79	    Tail,
80	}
81	
82	/// How many rows a question takes besides its table's: its box, status
83	/// line, table header, and end.
84	const QUESTION_ROWS: usize = 4;
85	
86	/// What a question's box, status line, and table header showed, as last laid
87	/// out, so they are measured again once that changes.
88	#[derive(Clone, Copy, Debug, PartialEq)]
89	struct Look {
90	    starts: bool,
91	    status: TaskStatus,
92	    empty: bool,
93	}
94	
95	/// What the list was last laid out for.
96	#[derive(Default)]
97	struct PaneLaidOut {
98	    keys: Vec<QuestionKey>,
99	    tables: Vec<TableSync>,
100	    looks: Vec<Option<Look>>,
101	    pending: bool,
102	}
103	
104	/// The Ask conversation of one project, kept while the application runs.
105	pub(super) struct AskPane {
106	    rows: MeasuredList,
107	    laid_out: RefCell<PaneLaidOut>,
108	    /// Its scroll stays at the bottom, following each question asked and
109	    /// each answer as it grows.
110	    pub(super) locked: bool,
111	    /// The question to scroll to once the pane is next laid out.
112	    reveal: Cell<Option<QuestionKey>>,
113	}
114	
115	impl AskPane {
116	    pub(super) fn new() -> Self {
117	        Self {
118	            rows: MeasuredList::new(task_table::OVERDRAW),
119	            laid_out: RefCell::default(),
120	            // It opens scrolled to the bottom, on the newest question.
121	            locked: true,
122	            reveal: Cell::new(None),
123	        }
124	    }
125	
126	    /// Scrolls to `key` once it is next laid out, leaving the bottom.
127	    pub(super) fn reveal(&mut self, key: QuestionKey) {
128	        self.locked = false;
129	        self.reveal.set(Some(key));
130	    }
131	
132	    #[cfg(test)]
133	    pub(super) fn rows(&self) -> &MeasuredList {
134	        &self.rows
135	    }
136	}
137	
138	/// Where each question's rows start, what row `ix` shows, and how each
139	/// question's table is laid out.
140	struct PaneLayout {
141	    starts: Vec<usize>,
142	    tables: Vec<TableLayout>,
143	}
144	
145	impl PaneLayout {
146	    fn row_at(&self, ix: usize) -> PaneRow {
147	        let question = match self.starts.binary_search(&ix) {
148	            Ok(question) => question,
149	            Err(0) => return PaneRow::Tail,
150	            Err(next) => next - 1,
151	        };
152	        let Some(table) = self.tables.get(question) else {
153	            return PaneRow::Tail;
154	        };
155	        let at = ix - self.starts[question];
156	        let items = table.items();
157	        match at {
158	            0 => PaneRow::Question(question),
159	            1 => PaneRow::Status(question),
160	            2 => PaneRow::TableHeader(question),
161	            at if at < items + 3 => PaneRow::TableRow(question, at - 3),
162	            at if at == items + 3 => PaneRow::End(question),
163	            _ => PaneRow::Tail,
164	        }
165	    }
166	}
167	
168	/// `secs`, seconds since the Unix epoch, in local time as `format` has it.
169	fn local_time(secs: u64, format: &str) -> Option<String> {
170	    let at = chrono::DateTime::from_timestamp(i64::try_from(secs).ok()?, 0)?;
171	    Some(at.with_timezone(&chrono::Local).format(format).to_string())
172	}
173	
174	/// Now, in seconds since the Unix epoch.
175	pub(super) fn now_secs() -> u64 {
176	    std::time::SystemTime::now()
177	        .duration_since(std::time::UNIX_EPOCH)
178	        .map_or(0, |since| since.as_secs())
179	}
180	
181	impl PromptMode {
182	    /// Every question of the project, oldest first: those saved with it, then
183	    /// those asked since.
184	    fn question_keys(&self) -> Vec<QuestionKey> {
185	        (0..self.answers.len())
186	            .map(QuestionKey::Answer)
187	            .chain(self.asks.iter().map(|ask| QuestionKey::Ask(ask.id)))
188	            .collect()
189	    }
190	
191	    fn question(&self, key: QuestionKey) -> Option<&PromptTask> {
192	        match key {
193	            QuestionKey::Answer(ix) => self.answers.get(ix),
194	            QuestionKey::Ask(id) => self
195	                .asks
196	                .iter()
197	                .find(|ask| ask.id == id)
198	                .map(|ask| &ask.task),
199	        }
200	    }
201	
202	    /// Whether each question begins a conversation: the first, and each whose
203	    /// record says it started one.
204	    fn conversation_starts(&self, keys: &[QuestionKey]) -> Vec<bool> {
205	        keys.iter()
206	            .enumerate()
207	            .map(|(ix, key)| {
208	                ix == 0
209	                    || self
210	                        .question(*key)
211	                        .is_some_and(|task| task.new_conversation)
212	            })
213	            .collect()
214	    }
215	
216	    /// Brings the question `id` into view: the Ask tab selected, its pane
217	    /// scrolled to the question.
218	    pub fn reveal_question(&mut self, id: usize, window: &mut Window, cx: &mut Context<Self>) {
219	        self.chat_input
220	            .update(cx, |input, cx| input.select_mode(SendMode::Ask, window, cx));
221	        self.on_ask_tab = true;
222	        self.ask_pane.reveal(QuestionKey::Ask(id));
223	        cx.notify();
224	    }
225	
226	    /// Stops the question `id`, if it is still running, leaving the others
227	    /// running. Its run's record is saved as far as it went.
228	    pub(super) fn stop_ask(&mut self, id: usize, cx: &mut Context<Self>) {
229	        if let Some(ask) = self.asks.iter_mut().find(|ask| ask.id == id)
230	            && ask.task.status.is_active()
231	        {
232	            ask.task.cancel();
233	            ask.task.end();
234	            ask.stopped.store(true, Ordering::SeqCst);
235	            // Dropping its run stops it, and saves what came of it.
236	            ask._run = Task::ready(());
237	            cx.notify();
238	        }
239	    }
240	
241	    /// Asks the question `key` again, as it was asked; it comes in at the
242	    /// bottom.
243	    fn resend_question(&mut self, key: QuestionKey, window: &mut Window, cx: &mut Context<Self>) {
244	        let Some(task) = self.question(key) else {
245	            return;
246	        };
247	        let (text, sent) = (task.text.to_string(), task.sent.clone());
248	        // Named after it, rather than titled again.
249	        let named_after = Some(task.name.to_string());
250	        if self.project_dir.is_none() {
251	            window.push_notification(
252	                Notification::error("Open a project before sending a prompt.")
253	                    .title("No project open"),
254	                cx,
255	            );
256	            return;
257	        }
258	        self.send_as(
259	            text,
260	            SendMode::Ask,
261	            sent.attached(),
262	            sent.sliced,
263	            None,
264	            None,
265	            false,
266	            named_after,
267	            window,
268	            cx,
269	        );
270	    }
271	
272	    /// Tells the list what changed since it was last laid out: questions
273	    /// asked or loaded, what their tables hold, and what each question's
274	    /// box, status line, and header show.
275	    fn lay_out_ask_pane(&self, keys: &[QuestionKey], cx: &App) -> PaneLayout {
276	        let rows = &self.ask_pane.rows;
277	        let mut laid_out = self.ask_pane.laid_out.borrow_mut();
278	        if laid_out.keys != keys {
279	            let kept = laid_out.keys.len();
280	            // The list holds its tail from the first time it is laid out.
281	            if rows.count() > 0 && kept <= keys.len() && keys[..kept] == laid_out.keys[..] {
282	                // Asked since: new questions come in above the tail.
283	                let tail = rows.count().saturating_sub(1);
284	                let added = keys.len() - kept;
285	                rows.splice(tail..tail, added * QUESTION_ROWS);
286	                laid_out
287	                    .tables
288	                    .extend((0..added).map(|_| TableSync::default()));
289	                laid_out.looks.extend((0..added).map(|_| None));
290	            } else {
291	                rows.reset(keys.len() * QUESTION_ROWS + 1);
292	                laid_out.tables = keys.iter().map(|_| TableSync::default()).collect();
293	                laid_out.looks = vec![None; keys.len()];
294	                laid_out.pending = false;
295	            }
296	            laid_out.keys = keys.to_vec();
297	        }
298	        let starts_conversation = self.conversation_starts(keys);
299	        let mut base = 0;
300	        let mut starts = Vec::with_capacity(keys.len());
301	        let mut tables = Vec::with_capacity(keys.len());
302	        for (ix, key) in keys.iter().enumerate() {
303	            starts.push(base);
304	            let Some(task) = self.question(*key) else {
305	                let layout = laid_out.tables[ix]
306	                    .layout()
307	                    .unwrap_or(TableLayout::of(&Reply::default(), None));
308	                tables.push(layout);
309	                base += QUESTION_ROWS + layout.items();
310	                continue;
311	            };
312	            let table = key.table();
313	            let layout = TableLayout::of(&task.reply, Some(self.steps_shown.contains(&table)));
314	            laid_out.tables[ix].update(rows, base + 3, table, &task.reply, layout, cx);
315	            let look = Look {
316	                starts: starts_conversation[ix],
317	                status: task.status,
318	                empty: task.reply.row_count() == 0,
319	            };
320	            if laid_out.looks[ix] != Some(look) {
321	                rows.remeasure(base..base + 3);
322	                let end = base + 3 + layout.items();
323	                rows.remeasure(end..end + 1);
324	                laid_out.looks[ix] = Some(look);
325	            }
326	            // While it runs, its status line follows the harness.
327	            if task.status.is_active() {
328	                rows.remeasure(base + 1..base + 2);
329	            }
330	            tables.push(layout);
331	            base += QUESTION_ROWS + layout.items();
332	        }
333	        let pending = self.ask_new_pending;
334	        if laid_out.pending != pending {
335	            rows.remeasure(base..base + 1);
336	            laid_out.pending = pending;
337	        }
338	        PaneLayout { starts, tables }
339	    }
