371	    /// A question's box, against the pane's right edge: the question as
372	    /// typed, with anything it was sent with beneath it, then when it was
373	    /// asked and, once it is over, Resend.
374	    fn question_row(
375	        &self,
376	        key: QuestionKey,
377	        task: &PromptTask,
378	        first: bool,
379	        starts: bool,
380	        cx: &mut Context<Self>,
381	    ) -> AnyElement {
382	        let theme = cx.theme();
383	        let id = key.id();
384	        let tint = Hsla {
385	            a: QUESTION_TINT,
386	            ..chat_input::mode_color(SendMode::Ask, cx)
387	        };
388	        let attached_text = task.sent.attached_text.iter().map(|text| {
389	            let lines = text.lines().count();
390	            h_flex()
391	                .gap_1p5()
392	                .min_w_0()
393	                .text_xs()
394	                .text_color(theme.muted_foreground)
395	                .child(Icon::new(IconName::TextQuote).xsmall().flex_none())
396	                .child(div().min_w_0().truncate().child(first_line(text)))
397	                .when(lines > 1, |row| {
