417	            );
418	        // Lets UI tests find the question; inert in normal builds.
419	        let bubble = gpui_kit::TestSupportExt::test_support(bubble);
420	        let asked = task.asked_at.and_then(|at| local_time(at, "%H:%M"));
421	        let done = !task.status.is_active();
422	        let this = cx.entity().downgrade();
423	        let footer = h_flex()
424	            .justify_end()
