441	            .pt(if first { px(12.) } else { QUESTION_GAP })
442	            .gap_1()
443	            .when(starts, |row| {
444	                row.child(
445	                    div()
446	                        .pb_2()
447	                        .child(Self::conversation_divider(id, task.asked_at, cx)),
448	                )
449	            })
450	            .child(h_flex().w_full().justify_end().child(bubble))
451	            .child(footer)
452	            .into_any_element()
453	    }
