455	    /// A question's status line: while it runs, a spinner, the latest thing
456	    /// the harness did, and Stop; once over, its status unless it is done.
457	    fn question_status(
458	        &self,
459	        key: QuestionKey,
460	        task: &PromptTask,
461	        cx: &mut Context<Self>,
462	    ) -> AnyElement {
463	        let id = key.id();
464	        if task.status.is_active() {
465	            let stop = match key {
466	                QuestionKey::Ask(ask) => Some(
467	                    Button::new(("stop-ask", ask))
468	                        .ghost()
469	                        .xsmall()
470	                        .icon(IconName::CircleStop)
471	                        .label("Stop")
472	                        .tooltip("Stop this question, leaving the others running")
473	                        .on_click(cx.listener(move |this, _, _, cx| this.stop_ask(ask, cx))),
474	                ),
475	                QuestionKey::Answer(_) => None,
476	            };
477	            let row = h_flex()
478	                .id(("question-status", id))
479	                .w_full()
480	                .px_4()
481	                .pt(ANSWER_GAP)
482	                .gap_2()
483	                .items_center()
484	                .child(div().flex_none().child(Spinner::new().small()))
485	                .child(
486	                    div()
487	                        .flex_1()
488	                        .min_w_0()
489	                        .child(latest_row(id, &task.reply, cx)),
490	                )
491	                .children(stop);
492	            return gpui_kit::TestSupportExt::test_support(row).into_any_element();
493	        }
494	        if task.status == TaskStatus::Done {
495	            return div().into_any_element();
496	        }
497	        div()
498	            .w_full()
499	            .px_4()
500	            .pt(ANSWER_GAP)
501	            .child(
502	                div()
503	                    .id(("task-status", id))
504	                    .flex_none()
505	                    .child(task.status.tag(cx)),
506	            )
507	            .into_any_element()
508	    }
509	
510	    /// The pane: its header, and the conversation beneath it, or, with no
511	    /// question asked yet, a note saying so.
512	    pub(super) fn render_ask_pane(&self, cx: &mut Context<Self>) -> AnyElement {
513	        let keys = self.question_keys();
514	        let theme = cx.theme();
515	        let (border, muted, ring) = (theme.border, theme.muted_foreground, theme.ring);
516	        let (tab_bar, background) = (theme.tab_bar, theme.background);
517	        let header = h_flex()
518	            .id("ask-pane-header")
519	            .flex_none()
520	            .h(ASK_HEADER_HEIGHT)
521	            .px(px(12.))
522	            .items_center()
523	            .justify_between()
524	            .bg(tab_bar)
525	            .border_b_1()
526	            .border_color(border)
527	            .child("Questions")
528	            .child(
529	                div()
530	                    .text_xs()
531	                    .text_color(muted)
532	                    .child(keys.len().to_string()),
533	            );
534	        let header = gpui_kit::TestSupportExt::test_support(header);
535	        let content = if keys.is_empty() {
536	            let empty = div()
537	                .id("ask-pane-empty")
538	                .text_color(muted)
539	                .text_center()
540	                .child("No questions yet. Ask one below.");
541	            div()
542	                .flex_1()
543	                .min_h_0()
544	                .flex()
545	                .items_center()
546	                .justify_center()
547	                .px_4()
548	                .child(gpui_kit::TestSupportExt::test_support(empty))
549	                .into_any_element()
550	        } else {
551	            self.render_conversation(&keys, cx)
552	        };
553	        let handle = div()
554	            .id("ask-split-resize")
555	            .group("ask-split-resize")
556	            .absolute()
557	            .top_0()
558	            .bottom_0()
559	            .left(-ASK_SPLIT_HANDLE / 2.)
560	            .w(ASK_SPLIT_HANDLE)
561	            .flex()
562	            .justify_center()
563	            .cursor_col_resize()
564	            .on_prepaint(|bounds, _, cx| {
565	                crate::hit_areas::register_resize("ask-split-resize".into(), bounds, cx)
566	            })
567	            .child(
568	                div()
569	                    .h_full()
570	                    .w(px(2.))
571	                    .group_hover("ask-split-resize", |line| line.bg(ring)),
572	            )
573	            .on_drag(AskSplitResize, |_, _, _, cx| cx.new(|_| EmptyView));
574	        let handle = gpui_kit::TestSupportExt::test_support(handle);
575	        let pane = v_flex()
576	            .id("ask-pane")
577	            .relative()
578	            .flex_none()
579	            .h_full()
580	            .w(relative(self.ask_split_share))
581	            .min_w_0()
582	            .bg(background)
583	            .border_l_1()
584	            .border_color(border)
585	            // A drag that selects some of a question's or answer's text
586	            // offers to copy it or attach it to the prompt, once the
587	            // selection has settled.
588	            .on_mouse_up(
589	                MouseButton::Left,
590	                cx.listener(|_, event: &MouseUpEvent, window, cx| {
591	                    let position = event.position;
592	                    cx.defer_in(window, move |this, window, cx| {
593	                        let text = TextSelection::selected_text(window, cx);
594	                        if !text.trim().is_empty() && this.on_ask_tab {
595	                            this.selection_popover = Some((position, text));
596	                            cx.notify();
597	                        }
598	                    });
599	                }),
600	            )
601	            .child(header)
602	            .child(content)
603	            .child(handle);
604	        gpui_kit::TestSupportExt::test_support(pane).into_any_element()
605	    }
606	
607	    /// Every question and its answer, oldest first, as one list that scrolls,
608	    /// laying out only what is in view.
609	    fn render_conversation(&self, keys: &[QuestionKey], cx: &mut Context<Self>) -> AnyElement {
610	        let layout = Rc::new(self.lay_out_ask_pane(keys, cx));
611	        let rows = &self.ask_pane.rows;
612	        if let Some(key) = self.ask_pane.reveal.take()
613	            && let Some(ix) = keys.iter().position(|k| *k == key)
614	        {
615	            rows.state().scroll_to(ListOffset {
616	                item_ix: layout.starts[ix],
617	                offset_in_item: px(0.),
618	            });
619	        } else if self.ask_pane.locked {
620	            rows.scroll_to_end();
621	        }
622	        let theme = cx.theme();
623	        let (border, muted) = (theme.border, theme.muted_foreground);
624	        let (table_background, radius) = (theme.tokens.table, theme.radius);
625	        let keys: Rc<Vec<QuestionKey>> = Rc::new(keys.to_vec());
626	        let starts = Rc::new(self.conversation_starts(&keys));
627	        let this = cx.entity().downgrade();
628	        let open_file = self.file_opener(cx);
629	        // Its tables tighten as the pane narrows, counting its padding.
630	        let density = task_table::Density::of_list(rows, px(32.));
631	        // Each question's table rows, finding its reply wherever it is kept.
632	        let tables: Rc<Vec<RenderRow>> = Rc::new(
633	            keys.iter()
634	                .zip(&layout.tables)
635	                .map(|(&key, &table_layout)| {
636	                    let reply_of = task_table::reply_of({
637	                        let this = this.clone();
638	                        move |cx| {
639	                            let prompt_mode = this.upgrade()?.read(cx);
640	                            prompt_mode.question(key).map(|task| &task.reply)
641	                        }
642	                    });
643	                    let steps = steps(key.table(), &self.steps_shown, &cx.entity());
644	                    task_table::table_rows(
645	                        key.table(),
646	                        reply_of,
647	                        table_layout,
648	                        Some(open_file.clone()),
649	                        Some(steps),
650	                        density,
651	                        cx,
652	                    )
653	                })
654	                .collect(),
655	        );
656	        let render: RenderRow = Rc::new(move |ix, window, cx| {
657	            let Some(entity) = this.upgrade() else {
658	                return div().into_any_element();
659	            };
660	            let row = layout.row_at(ix);
661	            let inset = || div().w_full().px_4();
662	            let question = |question: usize, cx: &App| -> Option<(QuestionKey, bool)> {
663	                let key = *keys.get(question)?;
664	                entity.read(cx).question(key)?;
665	                Some((key, starts[question]))
666	            };
667	            match row {
668	                PaneRow::Question(q) => {
669	                    let Some((key, starts)) = question(q, cx) else {
670	                        return div().into_any_element();
671	                    };
672	                    entity.update(cx, |this, cx| {
673	                        let Some(task) = this.question(key) else {
674	                            return div().into_any_element();
675	                        };
676	                        this.question_row(key, task, q == 0, starts, cx)
677	                    })
678	                }
679	                PaneRow::Status(q) => {
680	                    let Some((key, _)) = question(q, cx) else {
681	                        return div().into_any_element();
682	                    };
683	                    entity.update(cx, |this, cx| {
684	                        let Some(task) = this.question(key) else {
685	                            return div().into_any_element();
686	                        };
687	                        this.question_status(key, task, cx)
688	                    })
689	                }
690	                PaneRow::TableHeader(q) => {
691	                    let Some((key, _)) = question(q, cx) else {
692	                        return div().into_any_element();
693	                    };
694	                    let empty = entity
695	                        .read(cx)
696	                        .question(key)
697	                        .is_none_or(|task| task.reply.row_count() == 0);
698	                    if empty {
699	                        return inset()
700	                            .pt(ANSWER_GAP)
701	                            .text_color(muted)
702	                            .child("No output.")
703	                            .into_any_element();
704	                    }
705	                    inset()
706	                        .pt(ANSWER_GAP)
707	                        .child(
708	                            div()
709	                                .overflow_hidden()
710	                                .text_base()
711	                                .line_height(relative(1.5))
712	                                .rounded_t(radius)
713	                                .border_t_1()
714	                                .border_x_1()
715	                                .border_color(border)
716	                                .bg(table_background)
717	                                .child(task_table::output_header(density, cx)),
718	                        )
719	                        .into_any_element()
720	                }
721	                PaneRow::TableRow(q, row) => {
722	                    let Some(rows) = tables.get(q) else {
723	                        return div().into_any_element();
724	                    };
725	                    inset()
726	                        .child(
727	                            div()
728	                                .text_base()
729	                                .line_height(relative(1.5))
730	                                .border_x_1()
731	                                .border_color(border)
732	                                .bg(table_background)
733	                                .child(rows(row, window, cx)),
734	                        )
735	                        .into_any_element()
736	                }
737	                PaneRow::End(q) => {
738	                    let has_table = layout.tables.get(q).is_some_and(|table| table.items() > 0);
739	                    let id = keys.get(q).map_or(0, |key| key.id());
740	                    let end = inset().id(("question-end", id)).when(has_table, |end| {
741	                        end.child(
742	                            div()
743	                                .h(radius.max(px(1.)))
744	                                .rounded_b(radius)
745	                                .border_b_1()
746	                                .border_x_1()
747	                                .border_color(border)
748	                                .bg(table_background),
749	                        )
750	                    });
751	                    gpui_kit::TestSupportExt::test_support(end).into_any_element()
752	                }
753	                PaneRow::Tail => {
754	                    let pending = entity.read(cx).ask_new_pending;
755	                    inset()
756	                        .pt(if pending { QUESTION_GAP } else { px(0.) })
757	                        .pb(px(12.))
758	                        .when(pending, |tail| {
759	                            tail.child(Self::conversation_divider(usize::MAX, None, cx))
760	                        })
761	                        .into_any_element()
762	                }
763	            }
764	        });
765	        let list = div()
766	            .id("ask-pane-scroll")
767	            .flex_1()
768	            .min_h_0()
769	            .size_full()
770	            .child(rows.element(render))
771	            .child(task_table::follow_density(rows, density, px(32.)));
772	        let list = gpui_kit::TestSupportExt::test_support(list);
773	        let this = cx.entity().downgrade();
774	        let toggle: SetLock = Rc::new(move |locked, _, cx| {
775	            this.update(cx, |this, cx| {
776	                if this.ask_pane.locked != locked {
777	                    this.ask_pane.locked = locked;
778	                    cx.notify();
779	                }
780	            })
781	            .ok();
782	        });
783	        div()
784	            .flex_1()
785	            .min_h_0()
786	            .child(scrollbar::with_scrollbar(
787	                "ask-pane",
788	                rows,
789	                list,
790	                true,
791	                Some((self.ask_pane.locked, toggle)),
792	                cx,
793	            ))
794	            .into_any_element()
795	    }
796	
797	    /// Resizes the split so the pane's left edge is at `x`, within `bounds`,
798	    /// the space both sides share.
799	    pub(super) fn drag_ask_split(
800	        &mut self,
801	        x: Pixels,
802	        bounds: Bounds<Pixels>,
803	        cx: &mut Context<Self>,
804	    ) {
805	        if bounds.size.width <= px(0.) {
806	            return;
807	        }
808	        self.ask_split_share = ((bounds.right() - x) / bounds.size.width)
809	            .clamp(MIN_ASK_SPLIT_SHARE, MAX_ASK_SPLIT_SHARE);
810	        cx.notify();
811	    }
812	}
