    fn push_str(&mut self, delta: &str) {
        self.text.push_str(delta);
        self.shown = OnceCell::new();
    }

    /// The text as the markdown it is shown as.
    fn shown(&self) -> SharedString {
        self.shown
            .get_or_init(|| markdown::without_inline_code(&self.text).into())
            .clone()
    }
